      "confidence": "high"
    },
    {
      "rule_id": "t2",
      "verdict": "violation",
      "span": {
        "function": "every_custom_attribute_is_namespaced_and_never_uses_the_reserved_otel_prefix",
        "line": 85
      },
      "excerpt": "for key in attrs.keys().filter(|key| key.starts_with(\"kaibo.\")) { ... assert!(key.starts_with(\"kaibo.\") || key.starts_with(\"process.\"), ...)",
      "reason": "Test name claims all custom attributes are namespaced, but only checks kaibo.* ones; non-kaibo attributes escape.",
      "confidence": "high"
    }
