        "line": 81
      },
      "excerpt": "for key in attrs.keys().filter(|key| key.starts_with(\"kaibo.\")) {",
      "reason": "Guardrail discovers attributes dynamically, not from hardcoded list; new kaibo.* attributes caught automatically.",
      "confidence": "high"
    }
  ]
}
```
